INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(45911, 'Leviticus 9:5', 'Leviticus', 9, 5, 'نو هغوی ټول شیان د موسی د حکم سره سم د سپېڅلې خېمې مخې ته راوړل او ټول قوم د څښتن د عبادت دپاره هلته راټول شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_5.mp3', '', 1761754199, 1761754199),
(45912, 'Leviticus 9:6', 'Leviticus', 9, 6, 'موسی وویل: «څښتن تاسو ته حکم کړی دی چې دا کار وکړئ، ترڅو د هغه جلال تاسو ته ښکاره شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_6.mp3', '', 1761754199, 1761754199),
(45913, 'Leviticus 9:7', 'Leviticus', 9, 7, 'بیا موسی هارون ته وویل: «د قربانۍ ځای ته لاړ شه او لکه څنګه چې څښتن حکم کړی دی لومړی د خپل ځان او بیا د قوم د ګناهونو د کفارې د ادا کولو په خاطر د ګناه نذرانه او سوځېدونکې نذرانه وړاندې کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_7.mp3', '', 1761754199, 1761754199),
(45914, 'Leviticus 9:8', 'Leviticus', 9, 8, 'نو هارون د قربانۍ ځای ته لاړ او د ځان دپاره یې د ګناه د نذرانې په توګه خوسی حلال کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_8.mp3', '', 1761754199, 1761754199),
(45915, 'Leviticus 9:9', 'Leviticus', 9, 9, 'د هغه زامنو هغه ته وینه راوړله او هغه خپله ګوته په وینه کې غوټه کړه او د هغې څخه یې لږه د قربانۍ د ځای په ښکرونو باندې وسولوله. پاتې وینه یې د قربانۍ د ځای په بېخ کې توی کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_9.mp3', '', 1761754199, 1761754199),
(45916, 'Leviticus 9:10', 'Leviticus', 9, 10, 'لکه څنګه چې څښتن موسی ته حکم کړی ؤ، هغه د قربانۍ په ځای باندې د ګناه د نذرانې څخه وازګه، پښتورګي او د اینې ډېره ښه برخه وسوځوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_10.mp3', '', 1761754199, 1761754199),
(45917, 'Leviticus 9:11', 'Leviticus', 9, 11, 'خو غوښه او پوستکی یې د کمپ څخه دباندې وسوځول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_11.mp3', '', 1761754199, 1761754199),
(45918, 'Leviticus 9:12', 'Leviticus', 9, 12, 'هارون هغه حیوان حلال کړ چې د هغه د خپلې سوځېدونکې نذرانې دپاره ؤ. هغه ته خپلو زامنو وینه راوړله او هغه دا وینه د قربانۍ د ځای په څلورو خواو باندې وشیندله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_12.mp3', '', 1761754199, 1761754199),
(45919, 'Leviticus 9:13', 'Leviticus', 9, 13, 'هغوی هارون ته سر او د حیوان نورې ټوټې ورکړې او هغه یې د قربانۍ په ځای باندې وسوځول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_13.mp3', '', 1761754199, 1761754199),
(45920, 'Leviticus 9:14', 'Leviticus', 9, 14, 'هغه د نس دنننۍ برخې او شاتنۍ پښې ووینځلې او د قربانۍ په ځای باندې یې د سوځېدونکې نذرانې دپاسه وسوځولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_14.mp3', '', 1761754199, 1761754199),
(45921, 'Leviticus 9:15', 'Leviticus', 9, 15, 'بیا هارون هغه نذرانه راوړله چې د قوم دپاره وه. ده هغه سېرلی چې د قوم د ګناه دپاره ؤ، حلال کړ او هغه یې د ګناه د نذرانې دپاره وړاندې کړ، لکه څنګه چې هغه د خپلې ګناه دپاره وړاندې کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_15.mp3', '', 1761754199, 1761754199),
(45922, 'Leviticus 9:16', 'Leviticus', 9, 16, 'همدارنګه هغه سوځېدونکې نذرانه راوړله او هغه یې د اصولو له مخې وړاندې کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_16.mp3', '', 1761754199, 1761754199),
(45923, 'Leviticus 9:17', 'Leviticus', 9, 17, 'بیا یې د غلې دانې نذرانه وړاندې کړه، د هغې څخه یې یو موټی واخیست او هغه یې د قربانۍ په ځای باندې برسېره په هغې سوځېدونکې نذرانې چې هر سهار تیاریږي، وسوځاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_17.mp3', '', 1761754199, 1761754199),
(45924, 'Leviticus 9:18', 'Leviticus', 9, 18, 'هارون غویی او پسه د قوم دپاره د سلامتۍ د نذرانې په توګه حلال کړل. د هغه زامنو هغه ته وینه راوړله او هغه دا وینه د قربانۍ د ځای په څلورو خواو باندې وشیندله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_18.mp3', '', 1761754199, 1761754199),
(45925, 'Leviticus 9:19', 'Leviticus', 9, 19, 'هغوی د غویي او د پسه وازګینې برخې، لم، د وازګې پرده، پښتورګي او د اینې ډېره ښه برخه واخیستل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_19.mp3', '', 1761754199, 1761754199),
(45926, 'Leviticus 9:20', 'Leviticus', 9, 20, 'او هغه یې د حیواناتو په سینو باندې کېښودل او بیا هارون وازګه د قربانۍ په ځای باندې وسوځوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_20.mp3', '', 1761754199, 1761754199),
(45927, 'Leviticus 9:21', 'Leviticus', 9, 21, 'څنګه چې موسی امر کړی ؤ، هارون د هغو حیواناتو سینې او شاتنۍ ښي پښې څښتن ته پورته ونیولې، ترڅو دا وښایي چې هغه څښتن ته وقف شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_21.mp3', '', 1761754199, 1761754199),
(45928, 'Leviticus 9:22', 'Leviticus', 9, 22, 'کله چې هارون د قربانیو مراسم سرته ورسول، نو خپل لاسونه یې د قوم خواته پورته ونیول او برکت یې ورته ورکړ او د قربانۍ د ځای څخه راښکته شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_22.mp3', '', 1761754199, 1761754199),
(45929, 'Leviticus 9:23', 'Leviticus', 9, 23, 'موسی او هارون سپېڅلې خېمې ته ورننوتل. کله چې هغوی راووتل، قوم ته یې برکت ورکړ او د څښتن جلال ټول قوم ته ښکاره شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_23.mp3', '', 1761754199, 1761754199),
(45930, 'Leviticus 9:24', 'Leviticus', 9, 24, 'د څښتن د حضور څخه اور نازل شو او سوځېدونکې نذرانه او وازګینې برخې یې د قربانۍ په ځای باندې وسوځولې. کله چې ټول قوم دا ولیدل، نو د خوشحالۍ چیغې یې ووهلې او په سجده شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_24.mp3', '', 1761754199, 1761754199),
(45931, 'Deuteronomy 28:1', 'Deuteronomy', 28, 1, 'که چېرې تاسو په وفادارۍ سره د خپل څښتن خدای اطاعت وکړئ او د هغه د ټولو امرونو څخه چې زه یې نن درکوم پیروي وکړئ، هغه به ستاسو قوم د نړۍ د نورو ټولو قومونو څخه لوی کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_1.mp3', '', 1761754199, 1761754199),
(45932, 'Deuteronomy 28:2', 'Deuteronomy', 28, 2, 'د خپل څښتن خدای اطاعت کوئ، نو دا ټول برکتونه به ستاسو شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_2.mp3', '', 1761754199, 1761754199),
(45933, 'Deuteronomy 28:3', 'Deuteronomy', 28, 3, 'څښتن به ستاسو په ښارونو او پټیو کې برکت واچوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_3.mp3', '', 1761754199, 1761754199),
(45934, 'Deuteronomy 28:4', 'Deuteronomy', 28, 4, 'څښتن به تاسو ته ډېر اولادونه، پرېمانه فصلونه او ډېرې پادې او رمې درکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_4.mp3', '', 1761754199, 1761754199),
(45935, 'Deuteronomy 28:5', 'Deuteronomy', 28, 5, 'څښتن به ستاسو د غلو دانو په فصلونو او په هغو خوړو کې برکت واچوي چې تاسو یې د هغو فصلونو څخه تیاروئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_5.mp3', '', 1761754199, 1761754199),
(45936, 'Deuteronomy 28:6', 'Deuteronomy', 28, 6, 'څښتن به ستاسو په هر کار کې برکت واچوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_6.mp3', '', 1761754199, 1761754199),
(45937, 'Deuteronomy 28:7', 'Deuteronomy', 28, 7, 'کله چې ستاسو دښمنان په تاسو باندې حمله کوي، څښتن به ستاسو سره مرسته وکړي چې هغوی ته ماتې ورکړئ. هغوی به د یوې لارې څخه حمله کوي، خو هرې خواته به ستاسو څخه تښتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_7.mp3', '', 1761754199, 1761754199),
(45938, 'Deuteronomy 28:8', 'Deuteronomy', 28, 8, 'ستاسو څښتن خدای به ستاسو په هر کار کې برکت واچوي او ستاسو ګودامونه به د غلو دانو څخه ډک کړي. هغه به تاسو ته په هغه ځمکه کې چې تاسو ته یې درکوي برکت درکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_8.mp3', '', 1761754199, 1761754199),
(45939, 'Deuteronomy 28:9', 'Deuteronomy', 28, 9, 'که چېرې تاسو د خپل څښتن خدای اطاعت وکړئ او د هغه هر امر په ځای کړئ، هغه به د خپلې وعدې سره سم ستاسو څخه خپل ځانګړی قوم جوړ کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_9.mp3', '', 1761754199, 1761754199),
(45940, 'Deuteronomy 28:10', 'Deuteronomy', 28, 10, 'بیا به د دنیا ټول قومونه وویني چې څښتن تاسو د خپل قوم په توګه غوره کړي یئ او هغوی به ستاسو څخه ووېریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_10.mp3', '', 1761754199, 1761754199),
(45941, 'Deuteronomy 28:11', 'Deuteronomy', 28, 11, 'څښتن به تاسو ته ډېر اولادونه، ډېر حیوانات او پرېمانه فصلونه په هغې خاوره کې درکړي چې ستاسو د نیکونو سره یې وعده کړې وه چې تاسو ته به یې درکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_11.mp3', '', 1761754199, 1761754199),
(45942, 'Deuteronomy 28:12', 'Deuteronomy', 28, 12, 'هغه به په سم وخت د خپلو غني اسماني ذخیرو څخه په تاسو باران ووروي او ستاسو په ټولو کارونو کې به برکت واچوي، ترڅو تاسو ډېرو قومونو ته پور ورکړئ، خو د هېڅ قوم څخه به څه شی په پور نه اخلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_12.mp3', '', 1761754199, 1761754199),
(45943, 'Deuteronomy 28:13', 'Deuteronomy', 28, 13, 'که چېرې تاسو د څښتن هغو ټولو امرونو ته چې زه یې نن درکوم په وفادارۍ سره غاړه کېږدئ، ستاسو څښتن خدای به ستاسو قوم د نورو قومونو په منځ کې پیرو نه بلکې مشر کړي، تاسو به تل بریالي یئ او هېڅکله به نه ناکامېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_13.mp3', '', 1761754199, 1761754199),
(45944, 'Deuteronomy 28:14', 'Deuteronomy', 28, 14, 'خو تاسو باید هېڅکله او په هېڅ ډول د دغو امرونو څخه سرغړونه ونه کړئ او نه د نورو خدایانو عبادت او خدمت وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_14.mp3', '', 1761754199, 1761754199),
(45945, 'Deuteronomy 28:15', 'Deuteronomy', 28, 15, 'خو که چېرې تاسو د خپل څښتن خدای نافرماني وکړئ او په وفادارۍ سره د هغه د ټولو فرمانونو او قوانینو څخه چې زه یې نن درکوم پیروي ونه کړئ، دا ټول لعنتونه به په تاسو باندې راشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_15.mp3', '', 1761754199, 1761754199),
(45946, 'Deuteronomy 28:16', 'Deuteronomy', 28, 16, 'څښتن به ستاسو په ښارونو او پټیو باندې لعنت ووایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_16.mp3', '', 1761754199, 1761754199),
(45947, 'Deuteronomy 28:17', 'Deuteronomy', 28, 17, 'څښتن به ستاسو د غلو دانو په فصلونو او په هغو خوړو باندې لعنت ووایي چې تاسو یې ورڅخه تیاروئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_17.mp3', '', 1761754199, 1761754199),
(45948, 'Deuteronomy 28:18', 'Deuteronomy', 28, 18, 'څښتن به تاسو ته د لږو اولادونو، خرابو فصلونو او لږو پادو او رمو په درکولو سره په تاسو باندې لعنت ووایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_18.mp3', '', 1761754199, 1761754199),
(45949, 'Deuteronomy 28:19', 'Deuteronomy', 28, 19, 'څښتن به ستاسو په هر کار باندې لعنت ووایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_19.mp3', '', 1761754199, 1761754199),
(45950, 'Deuteronomy 28:20', 'Deuteronomy', 28, 20, 'که چېرې تاسو بد کارونه وکړئ او څښتن رد کړئ، هغه به تر هغه وخته پورې ستاسو په هر کار کې افت، وارخطایي او تکلیف رامنځته کوي ترڅو تاسو زر او په پوره توګه تباه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_20.mp3', '', 1761754199, 1761754199),
(45951, 'Deuteronomy 28:21', 'Deuteronomy', 28, 21, 'هغه به تر هغه وخته پورې تاسو په دوامداره ناروغیو باندې اخته کوي، ترڅو ستاسو څخه هېڅوک په هغې خاورې کې پاتې نه شي چې تاسو به یې زر ونیسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_21.mp3', '', 1761754199, 1761754199),
(45952, 'Deuteronomy 28:22', 'Deuteronomy', 28, 22, 'څښتن به تاسو په ساري ناروغیو، پړسوب او تبې باندې اخته کړي. هغه به وچکالي او چڼاسکې رامنځته کړي او سوځوونکی باد به رانازل کړي چې ستاسو فصلونه له منځه یوسي. دا افتونه به په تاسو باندې تر هغه وخته پورې وي، ترڅو مړه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_22.mp3', '', 1761754199, 1761754199),
(45953, 'Deuteronomy 28:23', 'Deuteronomy', 28, 23, 'باران به هېڅ نه وریږي او ستاسو ځمکه به د اوسپنې په شان کلکه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_23.mp3', '', 1761754199, 1761754199),
(45954, 'Deuteronomy 28:24', 'Deuteronomy', 28, 24, 'د باران په ځای به څښتن د ګردونو او شګو توفانونه تر هغه وخته پورې په تاسو باندې نازلوي، ترڅو تاسو تباه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_24.mp3', '', 1761754199, 1761754199),
(45955, 'Deuteronomy 28:25', 'Deuteronomy', 28, 25, 'څښتن به ستاسو دښمنانو ته په تاسو باندې بری ورکړي. تاسو به د یوې لارې څخه په هغوی باندې حمله کوئ، خو د هغوی څخه به هرې خواته تښتئ او کله چې د دنیا ټول خلک دا پېښې وویني چې په تاسو باندې تېریږي، نو هغوی به سخت ووېریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_25.mp3', '', 1761754199, 1761754199),
(45956, 'Deuteronomy 28:26', 'Deuteronomy', 28, 26, 'کله چې تاسو مړه شئ، مرغان او وحشي حیوانات به راځي او ستاسو مړي به خوري او هېڅوک به نه وي چې هغوی وشړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_26.mp3', '', 1761754199, 1761754199),
(45957, 'Deuteronomy 28:27', 'Deuteronomy', 28, 27, 'څښتن به په تاسو باندې دانې راوخېژوي لکه څنګه چې هغه په مصریانو باندې راخېژولې وې. هغه به ستاسو په بدنونو باندې زخمونه راپیدا کړي. تاسو به د داغونو څخه ډک شئ او خارښت به درباندې ولګیږي، خو هېڅ علاج به یې نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_27.mp3', '', 1761754199, 1761754199),
(45958, 'Deuteronomy 28:28', 'Deuteronomy', 28, 28, 'څښتن به تاسو لېوني کړي، هغه به تاسو ړانده او وارخطا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_28.mp3', '', 1761754199, 1761754199),
(45959, 'Deuteronomy 28:29', 'Deuteronomy', 28, 29, 'تاسو به په رڼا ورځ د ړانده په شان لاس او پښې وهئ او خپله لاره به نه شئ پیدا کولای. په خپل هېڅ کار کې به نه بریالی کیږي. په تاسو باندې به تل ظلم کیږي او لوټل کېږئ به او هېڅوک به نه وي چې مرسته درسره وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_29.mp3', '', 1761754199, 1761754199),
(45960, 'Deuteronomy 28:30', 'Deuteronomy', 28, 30, 'تاسو به د یوې پېغلې سره کوژدن کوئ، خو بل سړی به په زور د هغې سره څملي. تاسو به کور جوړوئ، خو هېڅکله به په کې ونه اوسېږئ. تاسو به د انګورو باغ کرئ، خو هېڅکله به د هغه انګور ونه خورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_30.mp3', '', 1761754199, 1761754199),
(45961, 'Deuteronomy 28:31', 'Deuteronomy', 28, 31, 'ستاسو غویان به ستاسو په مخکې حلال کړای شي، خو تاسو به د هغو غوښه ونه خورئ. خره به مو په زور بېول کیږي او تاسو به ورته ګورئ، خو بېرته به تاسو ته نه درکول کیږي. ستاسو دښمنان به ستاسو پسونه بوځي او هېڅوک به نه وي چې مرسته درسره وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_31.mp3', '', 1761754199, 1761754199),
(45962, 'Deuteronomy 28:32', 'Deuteronomy', 28, 32, 'ستاسو زامن او لورګانې به ستاسو په مخکې پردیو خلکو ته د غلامانو په توګه ورکول کیږي. هره ورځ به تاسو خپلې اوښکې تویوئ او بېځایه به خپلو اولادونو ته سترګې په لاره یئ چې راستانه به شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_32.mp3', '', 1761754199, 1761754199),
(45963, 'Deuteronomy 28:33', 'Deuteronomy', 28, 33, 'یو پردی قوم به ستاسو ټول فصلونه چې تاسو په ډېر زحمت سره کرلي دي اخلي، خو تاسو به د دوامداره ظلم او بدې رویې څخه پرته هېڅ شی تر لاسه نه کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_33.mp3', '', 1761754199, 1761754199),
(45964, 'Deuteronomy 28:34', 'Deuteronomy', 28, 34, 'څه چې تاسو وینئ هغه به دومره وېروونکي وي چې تاسو به لېوني شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_34.mp3', '', 1761754199, 1761754199),
(45965, 'Deuteronomy 28:35', 'Deuteronomy', 28, 35, 'څښتن به تاسو ته داسې سزا درکړي چې د سر څخه نیولې تر پښو پورې د دردناکو دانو څخه ډک شئ چې هېڅ علاج به یې نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_35.mp3', '', 1761754199, 1761754199),
(45966, 'Deuteronomy 28:36', 'Deuteronomy', 28, 36, 'څښتن به تاسو او هغه پاچا چې تاسو به یې غوره کړئ، پرېږدي چې یو داسې پردي هېواد ته د اسیرانو په توګه بوتلل شئ چې نه تاسو او نه ستاسو نیکونو پېژانده. هلته به تاسو د داسې خدایانو عبادت کوئ چې د لرګیو او تیږو څخه جوړ شوي وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_36.mp3', '', 1761754199, 1761754199),
(45967, 'Deuteronomy 28:37', 'Deuteronomy', 28, 37, 'په هغو هېوادونو کې چې څښتن به تاسو په کې خپاره کړي، د هغو ځایونو خلک به د دې پېښو په لیدلو سره چې په تاسو باندې تېریږي له وېرې ولړزیږي او په تاسو باندې به ملنډې وهي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_37.mp3', '', 1761754199, 1761754199),
(45968, 'Deuteronomy 28:38', 'Deuteronomy', 28, 38, 'تاسو به په پوره اندازه تخم وکرئ، خو لږ حاصل به ورېبئ، ځکه چې ملخان به ستاسو فصلونه وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_38.mp3', '', 1761754199, 1761754199),
(45969, 'Deuteronomy 28:39', 'Deuteronomy', 28, 39, 'تاسو به د انګورو باغونه جوړ کړئ او د هغو ساتنه به وکړئ، خو انګور به ورڅخه راټول نه کړئ او د هغو شراب به ونه څښئ، ځکه چې تاکونه به چینجي وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_39.mp3', '', 1761754199, 1761754199),
(45970, 'Deuteronomy 28:40', 'Deuteronomy', 28, 40, 'ستاسو په وطن کې به په هرځای کې د زیتونو ونې شنې کیږي، خو د هغو په تېلو باندې به خپل ځانونه غوړ نه کړئ، ځکه چې زیتون به د پخېدلو څخه مخکې راغورځیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_40.mp3', '', 1761754199, 1761754199),
(45971, 'Deuteronomy 28:41', 'Deuteronomy', 28, 41, 'تاسو به زامن او لورګانې ولرئ، خو هغوی به له لاسه ورکړئ، ځکه چې هغوی به د جنګي اسیرانو په توګه بوتلل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_41.mp3', '', 1761754199, 1761754199),
(45972, 'Deuteronomy 28:42', 'Deuteronomy', 28, 42, 'ستاسو ټولې ونې او فصلونه به د ملخانو له خوا له منځه یووړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_42.mp3', '', 1761754199, 1761754199),
(45973, 'Deuteronomy 28:43', 'Deuteronomy', 28, 43, 'هغه پردي خلک چې ستاسو په خاوره کې اوسیږي، هغوی به نور هم شتمن او قدرتمند شي، خو تاسو به نور هم بې وزلي او کمزوري شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_43.mp3', '', 1761754199, 1761754199),
(45974, 'Deuteronomy 28:44', 'Deuteronomy', 28, 44, 'هغوی به پیسې ولري چې تاسو ته یې په پور درکړي، خو تاسو به هېڅ شی نه لرئ چې هغوی ته یې په پور ورکړئ. په پای کې به هغوی ستاسو مشران شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_44.mp3', '', 1761754199, 1761754199),
(45975, 'Deuteronomy 28:45', 'Deuteronomy', 28, 45, 'که چېرې تاسو د هغو ټولو قوانینو چې ستاسو څښتن خدای یې درکوي اطاعت ونه کړئ، نو هغه به دا ټول افتونه په تاسو باندې نازل کړي. دا افتونه به تر هغې پورې په تاسو باندې وي ترڅو تباه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_45.mp3', '', 1761754199, 1761754199),
(45976, 'Deuteronomy 28:46', 'Deuteronomy', 28, 46, 'دا به د تل دپاره په تاسو او ستاسو په اولادې باندې د څښتن د قضاوت نښه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_46.mp3', '', 1761754199, 1761754199),
(45977, 'Deuteronomy 28:47', 'Deuteronomy', 28, 47, 'څښتن تاسو ته په هر لحاظ برکت درکړ، خو تاسو په خوشحاله زړونو د هغه خدمت ونه کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_47.mp3', '', 1761754199, 1761754199),
(45978, 'Deuteronomy 28:48', 'Deuteronomy', 28, 48, 'په دې خاطر به څښتن ستاسو دښمنان راولیږي چې په تاسو باندې حمله وکړي او تاسو به د غلامانو په توګه د هغوی خدمت کوئ. تاسو به وږي، تږي، لوڅ او د هر شي دپاره به حاجتمند یئ. څښتن به ستاسو دښمنان دې ته پرېږدي چې په تاسو باندې سخت ظلم وکړي، ترڅو مړه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_48.mp3', '', 1761754199, 1761754199),
(45979, 'Deuteronomy 28:49', 'Deuteronomy', 28, 49, 'څښتن به د دنیا د بل سر څخه ستاسو په خلاف یو داسې قوم راولي چې تاسو به یې په ژبه نه پوهېږئ. هغوی به د عقاب په شان په تاسو باندې راښکته شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_49.mp3', '', 1761754199, 1761754199),
(45980, 'Deuteronomy 28:50', 'Deuteronomy', 28, 50, 'هغوی به بې رحمه وي او په هېچا به رحم نه کوي، نه په ځوانانو او نه په زړو خلکو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_50.mp3', '', 1761754199, 1761754199),
(45981, 'Deuteronomy 28:51', 'Deuteronomy', 28, 51, 'هغوی به ستاسو حیوانات او فصلونه واخلي او تاسو به د لوږې څخه مړه شئ. هغوی به تاسو ته هېڅ غلې دانې، شراب، د زیتونو تېل، پادې او رمې پرېنږدي او تاسو به مړه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_51.mp3', '', 1761754199, 1761754199),
(45982, 'Deuteronomy 28:52', 'Deuteronomy', 28, 52, 'هغوی به ټول ښارونه چې په هغه خاوره کې دي چې خپل څښتن خدای یې درکوي کلابند کړي او هغه لوړ او قوي دېوالونه به راوغورځوي چې تاسو ورباندې ډاډه یئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_52.mp3', '', 1761754199, 1761754199),
(45983, 'Deuteronomy 28:53', 'Deuteronomy', 28, 53, 'د هغو تکلیفونو له امله چې ستاسو دښمنان به یې د محاصرې په وخت کې په تاسو باندې راولي، تاسو به دومره وږي شئ چې حتی خپل اولادونه به چې خپل څښتن خدای درکړي دي هم وخورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_53.mp3', '', 1761754199, 1761754199),
(45984, 'Deuteronomy 28:58', 'Deuteronomy', 28, 58, 'که چېرې تاسو د خدای د ټولو قوانینو څخه چې په دې کتاب کې لیکلي دي په وفادارۍ سره اطاعت ونه کړئ او د خپل څښتن خدای د جلالي او هیبتناکه نوم درناوی ونه کړئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_58.mp3', '', 1761754199, 1761754199),
(45985, 'Deuteronomy 28:59', 'Deuteronomy', 28, 59, 'هغه به تاسو او ستاسو اولاده په وېروونکو بلاګانو او داسې خطرناکو ناروغیو اخته کړي چې علاج به یې نه کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_59.mp3', '', 1761754199, 1761754199),
(45986, 'Deuteronomy 28:60', 'Deuteronomy', 28, 60, 'هغه به په تاسو باندې هغه ټولې ناروغۍ راولي چې په مصر کې ورڅخه وېرېدلئ او هېڅکله به روغ نه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_60.mp3', '', 1761754199, 1761754199),
(45987, 'Deuteronomy 28:61', 'Deuteronomy', 28, 61, 'حتی هغه به تاسو په هر ډول ناروغیو او بلاګانو باندې چې د خدای د قوانینو په دې کتاب کې ورڅخه یادونه نه ده شوې، هم اخته کړي او تباه به شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_61.mp3', '', 1761754199, 1761754199),
(45988, 'Deuteronomy 28:62', 'Deuteronomy', 28, 62, 'که څه هم یو وخت ستاسو شمېر د اسمان د ستورو په شان زیات ؤ، خو ستاسو څخه به یوازې څو تنه ژوندي پاتې شي، ځکه چې تاسو د خپل څښتن خدای اطاعت ونه کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_62.mp3', '', 1761754199, 1761754199),
(45989, 'Deuteronomy 28:63', 'Deuteronomy', 28, 63, 'لکه څنګه چې څښتن خوشحاله ؤ چې ستاسو سره نېکي وکړي او ستاسو شمېر زیات کړي، همداسې به هغه خوشحاله شي چې تاسو له منځه یوسي او تباهي درباندې راولي. تاسو به د هغې خاورې څخه چې زر به یې ونیسئ بیخي وویستل شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_63.mp3', '', 1761754199, 1761754199),
(45990, 'Deuteronomy 28:64', 'Deuteronomy', 28, 64, 'څښتن به تاسو د دنیا د یو سر څخه تر بل سره پورې په ټولو قومونو کې خپاره کړي او هلته به د داسې خدایانو عبادت کوئ چې د لرګیو او تیږو څخه جوړ شوي وي، د داسې خدایانو چې نه تاسو او نه ستاسو نیکونو مخکې د هغو عبادت کړی وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_64.mp3', '', 1761754199, 1761754199),
(45991, 'Deuteronomy 28:65', 'Deuteronomy', 28, 65, 'تاسو به په هېڅ ځای کې ارامي نه مومئ، تل به د کور په ارمان یئ. څښتن به تاسو په اندېښنو، نا امیدۍ او مایوسۍ کې غرق کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_65.mp3', '', 1761754199, 1761754199),
(45992, 'Deuteronomy 28:66', 'Deuteronomy', 28, 66, 'ستاسو ژوند به تل په خطر کې وي. تاسو به شپه او ورځ سخت وېرېږئ او د مرګ په دوامداره وېره کې به ژوند کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_66.mp3', '', 1761754199, 1761754199),
(45993, 'Deuteronomy 28:67', 'Deuteronomy', 28, 67, 'تاسو چې هر شي ته ګورئ، نو زړونه به مو د وېرې د لاسه درزیږي. هر سهار به وایئ، کاشکې شپه وای او هره شپه به وایئ، کاشکې سهار وای.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_67.mp3', '', 1761754199, 1761754199),
(45994, 'Deuteronomy 28:68', 'Deuteronomy', 28, 68, 'څښتن به تاسو بېرته په کشتۍ ګانو کې مصر ته ولېږي که څه هم هغه ویلي وو چې تاسو به هېڅکله نه مجبوره کېږئ چې بیا هلته لاړ شئ. هلته به تاسو د دې هڅه کوئ چې خپل ځانونه په خپلو دښمنانو باندې د غلامانو په توګه خرڅ کړئ، خو هېڅوک به تاسو نه اخلي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy28_verse_68.mp3', '', 1761754199, 1761754199),
(45995, 'Psalms 117:1', 'Psalms', 117, 1, 'ای ټولو قومونو، د څښتن ثنا او صفت وکړئ ای ټولو خلکو، د هغه لویي بیان کړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms117_verse_1.mp3', '', 1761754199, 1761754199),
(45996, 'Psalms 117:2', 'Psalms', 117, 2, 'هغه زمونږ سره کړي مینه تلپاتې او وفاداري یې ده تر ابده پورې د څښتن ثنا او صفت وکړئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms117_verse_2.mp3', '', 1761754199, 1761754199),
(45997, 'Joshua 1:1', 'Joshua', 1, 1, 'د موسی د مړینې څخه وروسته څښتن د موسی د مرستیال د نون زوی یوشع سره خبرې وکړې، هغه وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua1_verse_1.mp3', '', 1761754199, 1761754199),
(45998, 'Joshua 1:2', 'Joshua', 1, 2, '«زما خدمتګار موسی مړ شوی دی. اوس ته د ټول قوم سره تیار شه او د اردن د سیند څخه هغې ځمکې ته واوړه چې زه یې اسراییلیانو ته ورکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua1_verse_2.mp3', '', 1761754199, 1761754199),
(45999, 'Joshua 1:3', 'Joshua', 1, 3, 'لکه څنګه چې ما د موسی سره وعده کړې وه، په هرځای چې تاسو قدم کېږدئ هغه به تاسو ته درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua1_verse_3.mp3', '', 1761754199, 1761754199),
(46000, 'Joshua 1:4', 'Joshua', 1, 4, 'ستاسو سیمه به د جنوبي دښتې څخه د لبنان تر غرونو پورې او د فرات د لوی سیند یعنې د حیتیانو د ټول هېواد څخه په لوېدیځ کې د مدیترانې تر بحیرې پورې ورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua1_verse_4.mp3', '', 1761754199, 1761754199),
(46001, 'Joshua 1:5', 'Joshua', 1, 5, 'ای یوشع، ترڅو چې ته ژوندی یې هېڅوک به ونه شي کولای چې ماتې درته درکړي. زه به ستا سره مل یم لکه څنګه چې د موسی سره وم. زه به تل ستا سره مل یم او تا به هېڅکله پرېنږدم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua1_verse_5.mp3', '', 1761754199, 1761754199),
(46002, 'Joshua 1:6', 'Joshua', 1, 6, 'نو قوي او زړور اوسه، ځکه څنګه چې دغه قوم هغه ځمکه چې د هغو د نیکونو سره مې وعده کړې ده نیسي، نو ته به د هغوی مشري کوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua1_verse_6.mp3', '', 1761754199, 1761754199),
(46003, 'Joshua 1:7', 'Joshua', 1, 7, 'نو قوي او ډېر زړور اوسه. په غور سره د هغه ټول شریعت څخه چې زما خدمتګار موسی درته درکړی دی اطاعت وکړه. د هغه هېڅ کومه برخه له پامه ونه غورځوې، نو ته به په هرځای کې بریالی اوسې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua1_verse_7.mp3', '', 1761754199, 1761754199),
(46004, 'Joshua 1:8', 'Joshua', 1, 8, 'ستاسو په هغه عبادت کې چې په ګډه سره کیږي باید تل د تورات کتاب په لوړ اواز سره ولولې. هغه شپه او ورځ مطالعه کړه او هرڅه چې په هغه کې لیکل شوي دي په غور سره د هغو څخه اطاعت وکړه. نو بیا به ته نېکمرغه او بریالی اوسې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua1_verse_8.mp3', '', 1761754199, 1761754199),
(46005, 'Joshua 1:9', 'Joshua', 1, 9, 'دا په یاد ساته چې ما تاته حکم کړی دی چې قوي او زړور اوسه. مه وېرېږه او جرات له لاسه مه ورکوه. زه ستا څښتن خدای یم او هر چېرته چې ځې، زه به ستا سره مل یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua1_verse_9.mp3', '', 1761754199, 1761754199),
(46006, 'Joshua 1:10', 'Joshua', 1, 10, 'نو یوشع د اسراییلو مشرانو ته حکم وکړ:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua1_verse_10.mp3', '', 1761754199, 1761754199),
(46007, 'Joshua 1:11', 'Joshua', 1, 11, '«په کمپ کې وګرځئ او خلکو ته ووایئ: ‹یو څه خواړه تیار کړئ، ځکه چې تاسو به په درې ورځو کې د اردن د سیند څخه پورې وځئ او هغه ځمکه به ونیسئ چې زمونږ څښتن خدای یې درکوي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua1_verse_11.mp3', '', 1761754199, 1761754199),
(46008, 'Joshua 1:12', 'Joshua', 1, 12, 'یوشع د روبین، جاد او د منسي نیمې قبیلې ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua1_verse_12.mp3', '', 1761754199, 1761754199),
(46009, 'Joshua 1:13', 'Joshua', 1, 13, '«په یاد ساتئ چې لکه څنګه چې د څښتن خدمتګار موسی تاسو ته ویلي وو چې زمونږ څښتن خدای به تاسو ته دا ځمکه چې د اردن د سیند په ختیځه غاړه پرته ده، درکړي چې هلته په سوله کې ژوند وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua1_verse_13.mp3', '', 1761754199, 1761754199),
(46010, 'Joshua 1:14', 'Joshua', 1, 14, 'ستاسو ښځې، ماشومان او څاروي به دلته پاتې شي، خو ستاسو هغه کسان چې په وسلو باندې سمبال دي، باید د نورو اسراییلیانو څخه مخکې د سیند څخه تېر شي چې د هغوی سره مرسته وکړي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua1_verse_14.mp3', '', 1761754199, 1761754199);